<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
use DigiForge\Portal\ReviewedScopedPolicy;
use DigiForge\Core\Settings;

final class ReviewedScopedPolicyTest extends WP_UnitTestCase {
 private array $actors;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();Settings::protectProduction();$this->actors=ReviewedLocalFixture::actors();wp_set_current_user($this->actors['author']);}
 private function input(string $scope='SHOP',bool $enabled=true):array {return ['environment'=>'production','scope'=>$scope,'workflow'=>$scope==='SHOP'?'':'research','capability'=>'research','enabled'=>$enabled];}
 private function approved(array $input):array {$p=ReviewedScopedPolicy::propose('digital',$input,time()-10,time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);$r=ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4());self::assertNotWPError($r);wp_set_current_user($this->actors['author']);return $r;}
 public function testMissingPolicyDeniesAndNeverGrantsExecution():void {$r=ReviewedScopedPolicy::evaluate('digital','production','research','research');self::assertFalse($r['effective_enabled']);self::assertFalse($r['external_execution_authorized']);}
 public function testRejectsUntypedUnknownAndExcludedInputs():void {foreach([['enabled'=>1],['extra'=>true],['capability'=>'stop_all'],['capability'=>'gst_automation'],['capability'=>'research_activation_authorized'],['workflow'=>'invented','scope'=>'WORKFLOW'],['scope'=>'shop'],['environment'=>'PRODUCTION']] as $change)self::assertWPError(ReviewedScopedPolicy::propose('digital',array_replace($this->input(),$change),time(),time()+3600,wp_generate_uuid4(),0));}
 public function testAuthorCannotApproveAndStaleRevisionCannotApprove():void {$p=ReviewedScopedPolicy::propose('digital',$this->input(),time(),time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);self::assertWPError(ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));wp_set_current_user($this->actors['reviewer']);self::assertWPError(ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision']+1,$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));}
 public function testParentVetoAndStopAllAlwaysPrevail():void {$this->approved($this->input('SHOP',false));$this->approved($this->input('WORKFLOW'));$r=ReviewedScopedPolicy::evaluate('digital','production','research','research');self::assertFalse($r['shop_enabled']);self::assertTrue($r['workflow_enabled']);self::assertFalse($r['effective_enabled']);self::assertFalse($r['external_execution_authorized']);self::assertTrue(Settings::get('stop_all'));}
 public function testReviewedTruePoliciesStillRespectStopAll():void {$this->approved($this->input());$this->approved($this->input('WORKFLOW'));$r=ReviewedScopedPolicy::evaluate('digital','production','research','research');self::assertTrue($r['shop_enabled']);self::assertTrue($r['workflow_enabled']);self::assertFalse($r['global_enabled']);self::assertFalse($r['effective_enabled']);}
 public function testRevocationAndForeignShopCannotSupplyApproval():void {$p=$this->approved($this->input());self::assertWPError(ReviewedScopedPolicy::current('jewelry',$p['policy_key']));wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision'],$p['proposal_hash'],'REVOKED',wp_generate_uuid4()));self::assertFalse(ReviewedScopedPolicy::evaluate('digital','production','research','research')['shop_enabled']);}
 public function testEffectiveDateCannotBeBypassed():void {$p=ReviewedScopedPolicy::propose('digital',$this->input(),time()+600,time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));self::assertFalse(ReviewedScopedPolicy::evaluate('digital','production','research','research')['shop_enabled']);}
 public function testExpiredWindowAndAlteredProposalHashCannotApprove():void {self::assertWPError(ReviewedScopedPolicy::propose('digital',$this->input(),time()-120,time()-60,wp_generate_uuid4(),0));$p=ReviewedScopedPolicy::propose('digital',$this->input(),time(),time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);self::assertWPError(ReviewedScopedPolicy::decide('digital',$p['policy_key'],$p['revision'],str_repeat('0',64),'APPROVED',wp_generate_uuid4()));self::assertFalse(ReviewedScopedPolicy::evaluate('digital','production','research','research')['shop_enabled']);}

}
